// Given
  type enumerated EWeekDays {
     Mon, Tue, Wed, Thu, Fri, Sat, Sun
  };
  type enumerated EWorkDays {
     Mon, Tue, Wed, Thu, Fri
  };
  type enumerated EDesWeekDays {
     Tue, Wed, Thu, Fri, Sat, Sun, Mon
  };

var EWeekDays v_myWeekDayMon := Mon
 var EWeekDays v_myWeekDaySun := Sun
 var EWorkDays v_myWorkDayMon := Mon
 var EDesWeekDays v_myDesWeekDayMon := Mon
 // Then
 v_myWeekDayMon == v_myWorkDayMon;
   // returns true
 v_myWeekDaySun == v_myWorkDayMon;
   // returns false, because Sun is not a possible value in EworkDays
 v_myDesWeekDayMon == v_myWeekDayMon;
   // returns false: though the identifiers in both enumerated types are the same,
   // but the integer values associated with the identifiers are different

// Given
 type set S1 {
        integer a1 optional,
        integer a2 optional,
        integer a3 optional
        };
 type set S2 {
        integer b1 optional,
        integer b2 optional,
        integer b3 optional
        };
 type set S3 {
        integer c1 optional,
        integer c2 optional,
        };
 type set of integer SI;
 type union U1 {
        integer d1,
        integer d2,
        };
 type union U2 {
        integer e1,
        integer e2,
        };
 type union U3 {
        integer d1,
        integer d2,
        boolean d3
        };
 // And
 const S1 c_s1 := { a1 := 0, a2 := omit, a3 := 2 };
   // Notice that the order of defining values of the fields does not matter
 const S2 c_s2a := { b1 := 0, b3 := 2, b2 := omit };
 const S2 c_s2b := { b2 := 0, b3 := 2, b1 := omit };
 const S3 c_s3 := { c1 := 0, c2 :=2 };
 var SI v_si:= { 0, -, 2 };
 const SI c_si := { 0, 2 };
 const U1 c_u1 := { d1:= 0 };
 const U2 c_u2 := { e1:= 0 };
 const U3 c_u3; := { d1:= 0 };
 // Then
 c_s1 == c_s2a;
   // returns true
 c_s1 == c_s2b;
   // returns false, because neither a1 nor a2 are equal to their counterparts
   // (the corresponding element is not omitted)
 c_s1 == c_s3;
   // returns false, because the effective value structures of s1 and s3 are not compatible
 c_s1 == v_si;
   // causes test case error as v_si is not completely initialized
   // (2nd element is left uninitialized)
 c_s1 == c_si;

// returns false, as the counterpart of the omitted a2 is 2,
     // but the counterpart of a3 is undefined 
  c_s3 == c_si;
     // returns true
  c_u1 == c_u2;
     // causes error as U1 and U2 have no common subset of alternatives
  c_u1 == c_u3;
     // returns true, as alternatives with the same names are chosen and 
     // the actual values in the selected alternatives are equal
  { 0, omit, 2 } == c_s1;
    // returns true
  c_s2a == { b1 := 0, b2:= omit, b3 := 2 };
    // returns true
  { c_s1, c_s2b } == { c_s2a, c_s1 };
    // returns false because c_s2b != c_s1
  { c_s1, c_s2b, c_s2a } == { c_s1 };
    // returns false because of different length
  c_s1.a1 == c_s2a.b1;
    // returns true, both fields are initialized with values and the values are equal
  c_s1.a2 == c_s2a.b2;
    // returns true, both fields are omit
  c_s1.a1 == c_s2a.b2;
    // returns false, value vs. omit
  c_s1.a1 == omit;
    // error, omit is neither a value nor a field reference
  c_s1.a2 == 3;
    // false, omit vs. value

// Given 
  type record MyRecord 
   {
     record {
      boolean innerField1 optional,
      integer innerField2 optional,
      MyRecord innerField3 optional
    } field1 optional,
      integer field2
     }
  var MyRecord v_myRecord := { field1 := {}, field2 := 5 }
  // type of field1 is record with fields, therefore field1 remains uninitialized
  // after this assignment (no value is assigned to any of the fields of vl_MyRecord.field1)
  var boolean v_checkResult := ispresent(v_myRecord.field1) // yields false
  v_myRecord.field1 := omit
  v_checkResult := ispresent(v_myRecord.field1) // yields false
  // and therefore, v_myRecord.field1.innerField1 is an inaccessible reference
  v_checkResult := ispresent(v_myRecord.field1.innerField3.field2) // yields false because 
  // innerField3 is unintialized and therefore, v_myRecord.field1.innerField3.field2 is an 
  // inaccessible reference
  v_checkResult := ispresent(v_myRecord.field1.innerField1) // yields false because field1
  // is omitted
  var template MyRecord v_myRecordT := { field1 := ?, field2 := 5 }
  v_checkResult := ispresent(v_myRecordT.field1) // yields true
  v_checkResult := ispresent(v_myRecordT.field1.innerField1) // yields false because field1 is
  // AnyValue (pls. note, that at expansion of field1 the optional field innerField1 obtains "*" 
  // that can match both a present and an omitted field
  type record R { integer f1 optional, integer f2 optional } 
  template R mw_t1 := {f1 := 1, f2 :=(2 .. 4) } 
  template R mw_t2 := { f1 := omit, f2 := (5, 7) ifpresent } 
  template R mw_t3 := {f1 := *, f2 :=? } 
  v_checkResult := ispresent(mw_t1.f1) // yields true 
  v_checkResult := ispresent(mw_t1.f2) // yields true 
  v_checkResult := ispresent(mw_t2.f1) // yields false 
  v_checkResult := ispresent(mw_t2.f2) // yields false
  v_checkResult := ispresent(mw_t3.f1) // yields false
  v_checkResult := ispresent(mw_t3.f2) // yields true

// inside module M:
  type union U { integer f1, octetstring f2 } 
  template U m_u1 := {f1 := 1} 
  template U mw_u2 := {f2 := ?} 
  template U mw_u3 := ? 
  template U m_u4 := ({ f1 := 2 }, {f2 := 'AB'O }) 
  template U mw_u5 := ({ f2 := '12?'O }, { f2 := '*34'O length(2) }) 
  var boolean v_checkResult := ischosen(m_u1.f1) // returns true 
  v_checkResult := ischosen(m_u1.f2) // yields false 
  v_checkResult := ischosen(mw_u2.f1) // yields false 
  v_checkResult := ischosen(mw_u2.f2) // yields true 
  v_checkResult := ischosen(mw_u3.f1) // yields false 
  v_checkResult := ischosen(mw_u3.f2) // yields false
  v_checkResult := ischosen(m_u4.f1) // yields false 
  v_checkResult := ischosen(m_u4.f2) // yields false 
  v_checkResult := ischosen(mw_u5.f1) // yields false 
  v_checkResult := ischosen(mw_u5.f2) // yields true 
  type record R { U u optional }
  template R m_r1 := { omit }
  var boolean v_checkResult := ischosen(m_r1.u.f1) // yields false

template anytype mw_a1 := { U := mw_u5 }
  template anytype mw_a2 := { M.U := { f1 := m_u1.f1 } }
  var boolean v_checkResult := ischosen(mw_a1.U)   // yields true
  v_checkResult := ischosen(mw_a1.M.U)  // yields true
  v_checkResult := ischosen(mw_a1.integer) // yields false
  v_checkResult := ischosen(mw_a2.U)    // yields true

// Given 
  type union MyUnion
     { PDU_type1 p1,
       PDU_type2 p2,
       PDU_type p3 
     }
  // and given that mw_myPDU is a template of MyUnion type
  // and v_receivedPDU is also of MyUnion type 
  // then 
  myPort.receive(mw_myPDU) -> value v_receivedPDU
  var boolean v_checkResult := ischosen(v_receivedPDU.p2)
  // yields true if the actual instance of mw_myPDU carries a PDU of the type PDU_type2

type record MyRec {
     integer f1 optional,
     integer f2 optional
  }
  var MyRec v_myRec;
  var template MyRec v_myRecT;
  var boolean_checkResult := isvalue(v_myRec);   // yields false
  v_checkResult := isvalue(v_myRecT);  // yields false
  v_myRec  := { f1 := 5, f2 := omit }
  v_myRecT := { f1 := ?, f2 := 5 }
  v_checkResult := isvalue(v_myRec);   // yields true
  v_checkResult := isvalue(v_myRec.f2); // yields false; 
  v_checkResult := isvalue(v_myRecT);  // yields false
  v_checkResult := isvalue(v_myRecT.f1); // yields false
  v_checkResult := isvalue(v_myRecT.f2); // yields true
  v_myRecT.f2 := omit;
  v_checkResult := isvalue(v_myRecT.f2); // yields false

type union MyUnion {
     integer ch1,
     integer ch2
  }
  template MyUnion m_myUnion := { ch1 := 5 }
  template MyUnion mw_myUnion := { ch1 := ? }
  var boolean v_checkResult := isvalue(m_myUnion);   // yields true
  v_checkResult := isvalue(mw_myUnion);   // yields false
  v_checkResult := isvalue(mw_myUnion.ch1); // yields false
  // note, this is different from ischosen(mw_myUnion.ch1) as isvalue checks the content of the 
  // choice ch1, while ischosen is checking if ch1 has been selected or not
  v_checkResult := isvalue(mw_myUnion.ch2); // yields false

type record MyRecord {
     MyUnion u optional 
  }
  template MyRecord m_myRecord := { u := m_myUnion }
  template MyRecord mw_myRecord := { u := mw_myUnion }
  template MyRecord m_myRecord2 := { u := omit }
  var boolean v_checkResult := isvalue(m_myRecord.u.ch1); // yields true
  v_checkResult := isvalue(mw_myRecord.u.ch1); // yields false
  v_checkResult := isvalue(mw_myRecord.u.ch2); // yields false
  v_checkResult := isvalue(m_myRecord.u.ch2); // yields false

type record MyRec {
     integer f1,
     MyRec f2 optional
  }
  var MyRec v_myRec;
  var boolean_checkResult := isbound(v_myRec); // yields false
  v_myRec.f2 := omit;
  checkResult := isbound(v_myRec);      // yields true as v_myRec is partially initialized,
                  // field f2 is set to omit
  v_myRec := { f1 := 5, f2 := omit }
  checkResult := isbound(v_myRec);      // yields true as v_myRec is completely initialized
  checkResult := isbound(v_myRec.f2.f1);   // yields false as v_myRec.f2.f1 is inaccessible
  checkResult := isbound(v_myRec.f1/0);   // shall cause an error already during evaluating the
                  // operand because the operand is not a reference and division by 
                  // zero causes a runtime error
  type union MyUnion {
     integer ch1,
     MyRec  ch2
  }
  var template MyUnion v_myUnion;
  checkResult := isbound(v_myUnion);    // yields false, as v_myUnion is uninitialized
  checkResult := isbound(v_myUnion.ch1);  // yields false, as alternative ch1 is uninitialized
  v_myUnion := { ch1 := 5 };
  checkResult := isbound(v_myUnion);    // yields true
  checkResult := isbound(v_myUnion.ch1);  // yields true
  checkResult := isbound(v_myUnion.ch2);  // yields false as the ch2 alternative is not selected
  checkResult := isbound(v_myUnion.ch2.f1); // yields false as the field f1 is inaccessible
  checkResult := isbound(v_myUnion.ch1/0); // shall cause an error already during evaluating the
                  // operand because the operand is not a reference and division by 
                  // zero causes a runtime error

type record PDU {
     PduHeader header,
     bitstring outerPayload
  }
  type record OuterPayload {
     OuterPayloadHeader header,
     universal charstring innerPayload
  }
  type record InnerPayload {
     integer data1,
     charstring data2
  }
  ...
  var PDU v_pdu;
  var InnerPayload v_inner;
  ... // v_pdu is filled with data;
  v_inner := v_pdu.outerPayload=>OuterPayload.innerPayload=>(InnerPayload, "UTF-8");
  // v_pdu.outerPayload field is first decoded into a value of the OuterPayload type
  // the innerPayload field of the decoding result is subsequently decoded into a value
  // of the InnerPayload type (using UTF-8 format for conversion into a bitstring)
